                    cells.append((y, x))
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if (0 <= ny < h and 0 <= nx < w and grid[ny][nx]
                                and component[ny][nx] < 0):
                            component[ny][nx] = next_id
                            queue.append((ny, nx))
                markers = [grid[y][x] for y, x in cells if grid[y][x] > 1]
